int choose(int n, int k)
{
    // Base case: empty set or selecting all elements
    if (k == 0 || k == n)
        return 1;

    // Recursive case: choose k elements from n‑1 and add the case where the last element is chosen
    return choose(n - 1, k - 1) + choose(n - 1, k);
}

