{
    // Base case: empty selection or selecting all elements.
    if (k == 0 || k == n)
        return 1;

    // Container for future work; holds the next recursion call.
    std::vector<std::pair<int, int>> work;
    work.emplace_back(n - 1, k - 1);
    work.emplace_back(n - 1, k);

    // Process each pending work item.
    while (!work.empty())
    {
        const auto& [remaining, selected] = work.front();
        work.erase(work.begin());

        // Recurse only if the remaining elements allow a selection.
        if (selected < remaining)
        {
            work.emplace_back(remaining - 1, selected + 1);
            work.emplace_back(remaining - 1, selected);
        }
    }

    // The container now holds the final result.
    return work.front().second;
}

