int gcd(int a, int b)
{
    // Use a std::stack for explicit control over the call stack.
    std::stack<int> stack;
    stack.push(a);
    stack.push(b);

    while (!stack.empty()) {
        int current = stack.top();
        stack.pop();

        if (current == 0) {
            continue; // Zero divisor yields zero.
        }

        int next = stack.top();
        stack.pop();

        // Compute next gcd using the standard Euclidean algorithm.
        stack.push(next % current);
    }

    // The final element in the stack is the greatest common divisor.
    return stack.top();
}

