void quicksort(int* values, int low, int high)
{
    if (low >= high)
        return; // base case: nothing to sort

    const int split = partition(values, low, high); // partition index
    // Recursively sort the left sub‑array
    quicksort(values, low, split - 1);
    // Recursively sort the right sub‑array
    quicksort(values, split + 1, high);
}

void quicksort(int* values, int low, int high)
{
    if (low >= high)
        return; // empty or already sorted

    // Use a std::vector for temporary storage; it avoids manual memory management.
    std::vector<int> work;
    work.reserve(high - low + 1); // avoid reallocations

    // Insert the first element as the first piece of work.
    work.push_back(values[low]);

    // Process the rest of the array in a single pass.
    for (int i = low + 1; i <= high; ++i) {
        if (values[i] < work.back()) {
            // Insert into the front of the work vector.
            work.insert(work.begin(), values[i]);
        } else {
            // Insert into the back of the work vector.
            work.push_back(values[i]);
        }
    }

    // Copy the partitioned pivot back to the original array.
    values[low] = work.front();

    // Recursively sort the two sub‑arrays.
    quicksort(values, low + 1, work.size() - 2);
    quicksort(values, work.size() + 1, high);
}

